window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5de486b11c8e7a72"]={"versions": [{"id": "FIG-5de486b11c8e7a72", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Template, M1/M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> Global Time Synchronization (GTS) im AUTOSAR BSW-Stack (in Verbindung mit dem Synchronized Time-Base Manager, <code>StbM</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der generischen Parameter für einen Zeitsklaven (<code>GlobalTimeSlave</code>) und dessen Spezialisierung für herstellerspezifische oder nicht-standardisierte Busprotokolle/CDDs (<code>UserDefinedGlobalTimeSlave</code>). Es ermöglicht die systemweite Deklaration von Timeout- und Plausibilisierungsmechanismen (Time Leap / Sprungerkennung) für empfangene Zeitbasen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeSlave</code> (abstrakte Basisklasse, kursiv):</strong></li>\n</ul>\n<p class=\"fig-p\">Definiert die standardisierten Schutz- und Filterparameter eines zeitsynchronisierten Slaves:</p>\n<ul class=\"fig-list\">\n<li><code>+ followUpTimeoutValue : TimeValue [0..1]</code>: Maximal zulässige Zeitspanne zwischen dem Empfang einer <code>SYNC</code>-Nachricht und der zugehörigen <code>FOLLOW_UP</code>-Nachricht (Zwei-Schritt-Synchronisationsverfahren).</li>\n<li><code>+ timeLeapFutureThreshold : TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Zukunft (positive Phasendiskrepanz gegenüber der lokalen Zeitbasis).</li>\n<li><code>+ timeLeapPastThreshold : TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Vergangenheit (negative Phasendiskrepanz).</li>\n<li><code>+ timeLeapHealingCounter : PositiveInteger [0..1]</code>: Anzahl aufeinanderfolgender, valider Synchronisationszyklen innerhalb der Schwellwerte, die erforderlich sind, um den Zustand eines zuvor detektierten Zeitsprungs (<code>Time Leap</code>) wieder aufzuheben (Entprellung/Heilung).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>UserDefinedGlobalTimeSlave</code> (konkrete Klasse):</strong></li>\n<li>Spezialisierung via UML-Generalisierung (Vererbungspfeil mit geschlossener Spitze) von <code>GlobalTimeSlave</code>.</li>\n<li>Kapselt Slave-Instanzen für proprietäre Netzwerke oder CDD-basierte Zeitquellen, für die kein nativer AUTOSAR-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) existiert, übernimmt dabei alle Überwachungsattribute der Basisklasse ohne eigene Zusatzattribute auf dieser Abstraktionsebene.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsmetadaten; zur Laufzeit steuern diese Attribute folgende Ablauflogik:</p>\n<ol class=\"fig-list\">\n<li><strong>Zwei-Schritt-Timeout (<code>followUpTimeoutValue</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer <code>SYNC</code>-PDU durch den Bus-Treiber/CDD.</li>\n<li>Start eines Software-Timers. Trifft die <code>FOLLOW_UP</code>-PDU nicht vor Ablauf von <code>followUpTimeoutValue</code> ein, wird der Synchronisationszyklus verworfen und ein Timeout-Flag an den <code>StbM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zeitsprungüberwachung (<code>timeLeapFutureThreshold</code> / <code>timeLeapPastThreshold</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Rekonstruktion der Master-Zeit $T_{Master}$ wird die Abweichung $\\Delta t = T_{Master} - T_{Local}$ berechnet.</li>\n<li>Überschreitet $\\Delta t > \\text{timeLeapFutureThreshold}$ oder $-\\Delta t > \\text{timeLeapPastThreshold}$, blockiert der Algorithmus die direkte Übernahme in die lokale Systemzeit oder triggert spezifische Synchronisationsfilter / DEM-Events.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Heilung (<code>timeLeapHealingCounter</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Feststellung eines Zeitsprungs inkrementiert jeder nachfolgende gültige Zyklus ($|\\Delta t| \\le \\text{Threshold}$) den internen Heilungszähler.</li>\n<li>Erst bei Erreichen von <code>timeLeapHealingCounter</code> gilt die Synchronisation wieder als stabil und fehlerfrei.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>StbM</code> / CDD-Generierung):</strong></li>\n<li>Die Attribute mappen direkt in BSW-Konfigurationsparameter (z. B. <code>StbMTimeLeapFutureThreshold</code>, <code>StbMTimeLeapPastThreshold</code>, <code>StbMTimeLeapHealingCounter</code>).</li>\n<li>Fehlen die optionalen Attribute (<code>[0..1]</code>), greift das Default-Verhalten: Deaktivierung der jeweiligen Prüfung oder Verwendung von Stack-Defaults.</li>\n<li><strong>Treiber- und CDD-Entwickler:</strong></li>\n<li>Bei Implementierung eines <code>UserDefinedGlobalTimeSlave</code> (meist via Complex Device Driver) muss die Schnittstelle zum <code>StbM</code> (<code>StbM_BusSetGlobalTime</code> bzw. synchronisierte Zeitstempelübergabe) die im System-Template definierten Schwellwerte berücksichtigen.</li>\n<li>Das Follow-up-Timeout muss auf die Task-Zykluszeit und Jitter-Toleranzen des verwendeten proprietären Übertragungsmediums abgestimmt sein.</li>\n</ul>"}, {"id": "FIG-90e0e09024cc377c", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Template, M1/M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> Global Time Synchronization (GTS) im AUTOSAR BSW-Stack (in Verbindung mit dem Synchronized Time-Base Manager, <code>StbM</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der generischen Parameter für einen Zeitsklaven (<code>GlobalTimeSlave</code>) und dessen Spezialisierung für herstellerspezifische oder nicht-standardisierte Busprotokolle/CDDs (<code>UserDefinedGlobalTimeSlave</code>). Es ermöglicht die systemweite Deklaration von Timeout- und Plausibilisierungsmechanismen (Time Leap / Sprungerkennung) für empfangene Zeitbasen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeSlave</code> (abstrakte Basisklasse, kursiv):</strong></li>\n</ul>\n<p class=\"fig-p\">Definiert die standardisierten Schutz- und Filterparameter eines zeitsynchronisierten Slaves:</p>\n<ul class=\"fig-list\">\n<li><code>+ followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Zeitspanne zwischen dem Empfang einer <code>SYNC</code>-Nachricht und der zugehörigen <code>FOLLOW_UP</code>-Nachricht (Zwei-Schritt-Synchronisationsverfahren).</li>\n<li><code>+ timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Zukunft (positive Phasendiskrepanz gegenüber der lokalen Zeitbasis).</li>\n<li><code>+ timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Vergangenheit (negative Phasendiskrepanz).</li>\n<li><code>+ timeLeapHealingCounter: PositiveInteger [0..1]</code>: Anzahl aufeinanderfolgender, valider Synchronisationszyklen innerhalb der Schwellwerte, die erforderlich sind, um den Zustand eines zuvor detektierten Zeitsprungs (<code>Time Leap</code>) wieder aufzuheben (Entprellung/Heilung).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>UserDefinedGlobalTimeSlave</code> (konkrete Klasse):</strong></li>\n<li>Spezialisierung via UML-Generalisierung (Vererbungspfeil mit geschlossener Spitze) von <code>GlobalTimeSlave</code>.</li>\n<li>Kapselt Slave-Instanzen für proprietäre Netzwerke oder CDD-basierte Zeitquellen, für die kein nativer AUTOSAR-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) existiert, übernimmt dabei alle Überwachungsattribute der Basisklasse ohne eigene Zusatzattribute auf dieser Abstraktionsebene.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsmetadaten; zur Laufzeit steuern diese Attribute folgende Ablauflogik:</p>\n<ol class=\"fig-list\">\n<li><strong>Zwei-Schritt-Timeout (<code>followUpTimeoutValue</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer <code>SYNC</code>-PDU durch den Bus-Treiber/CDD.</li>\n<li>Start eines Software-Timers. Trifft die <code>FOLLOW_UP</code>-PDU nicht vor Ablauf von <code>followUpTimeoutValue</code> ein, wird der Synchronisationszyklus verworfen und ein Timeout-Flag an den <code>StbM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zeitsprungüberwachung (<code>timeLeapFutureThreshold</code> / <code>timeLeapPastThreshold</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Rekonstruktion der Master-Zeit $T_{Master}$ wird die Abweichung $\\Delta t = T_{Master} - T_{Local}$ berechnet.</li>\n<li>Überschreitet $\\Delta t > \\text{timeLeapFutureThreshold}$ oder $-\\Delta t > \\text{timeLeapPastThreshold}$, blockiert der Algorithmus die direkte Übernahme in die lokale Systemzeit oder triggert spezifische Synchronisationsfilter / DEM-Events.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Heilung (<code>timeLeapHealingCounter</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Feststellung eines Zeitsprungs inkrementiert jeder nachfolgende gültige Zyklus ($|\\Delta t| \\le \\text{Threshold}$) den internen Heilungszähler.</li>\n<li>Erst bei Erreichen von <code>timeLeapHealingCounter</code> gilt die Synchronisation wieder als stabil und fehlerfrei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>StbM</code> / CDD-Generierung):</strong></li>\n<li>Die Attribute mappen direkt in BSW-Konfigurationsparameter (z. B. <code>StbMTimeLeapFutureThreshold</code>, <code>StbMTimeLeapPastThreshold</code>, <code>StbMTimeLeapHealingCounter</code>).</li>\n<li>Fehlen die optionalen Attribute (<code>[0..1]</code>), greift das Default-Verhalten: Deaktivierung der jeweiligen Prüfung oder Verwendung von Stack-Defaults.</li>\n<li><strong>Treiber- und CDD-Entwickler:</strong></li>\n<li>Bei Implementierung eines <code>UserDefinedGlobalTimeSlave</code> (meist via Complex Device Driver) muss die Schnittstelle zum <code>StbM</code> (<code>StbM_BusSetGlobalTime</code> bzw. synchronisierte Zeitstempelübergabe) die im System-Template definierten Schwellwerte berücksichtigen.</li>\n<li>Das Follow-up-Timeout muss auf die Task-Zykluszeit und Jitter-Toleranzen des verwendeten proprietären Übertragungsmediums abgestimmt sein.</li>\n</ul>"}, {"id": "FIG-9ade626629365ba1", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Template, M1/M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> Global Time Synchronization (GTS) im AUTOSAR BSW-Stack (in Verbindung mit dem Synchronized Time-Base Manager, <code>StbM</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der generischen Parameter für einen Zeitsklaven (<code>GlobalTimeSlave</code>) und dessen Spezialisierung für herstellerspezifische oder nicht-standardisierte Busprotokolle/CDDs (<code>UserDefinedGlobalTimeSlave</code>). Es ermöglicht die systemweite Deklaration von Timeout- und Plausibilisierungsmechanismen (Time Leap / Sprungerkennung) für empfangene Zeitbasen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeSlave</code> (abstrakte Basisklasse, kursiv):</strong></li>\n</ul>\n<p class=\"fig-p\">Definiert die standardisierten Schutz-, Sicherheits- und Filterparameter eines zeitsynchronisierten Slaves:</p>\n<ul class=\"fig-list\">\n<li><code>+ followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Zeitspanne zwischen dem Empfang einer <code>SYNC</code>-Nachricht und der zugehörigen <code>FOLLOW_UP</code>-Nachricht (Zwei-Schritt-Synchronisationsverfahren).</li>\n<li><code>+ icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code>: Konfigurationsparameter zur Verifikation des Integrity Check Value (ICV) zur Absicherung der Zeitnachrichten gegen Manipulation und Übertragungsfehler.</li>\n<li><code>+ timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Zukunft (positive Phasendiskrepanz gegenüber der lokalen Zeitbasis).</li>\n<li><code>+ timeLeapHealingCounter: PositiveInteger [0..1]</code>: Anzahl aufeinanderfolgender, valider Synchronisationszyklen innerhalb der Schwellwerte, die erforderlich sind, um den Zustand eines zuvor detektierten Zeitsprungs (<code>Time Leap</code>) wieder aufzuheben (Entprellung/Heilung).</li>\n<li><code>+ timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Vergangenheit (negative Phasendiskrepanz).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>UserDefinedGlobalTimeSlave</code> (konkrete Klasse):</strong></li>\n<li>Spezialisierung via UML-Generalisierung (Vererbungspfeil mit geschlossener Spitze) von <code>GlobalTimeSlave</code>.</li>\n<li>Kapselt Slave-Instanzen für proprietäre Netzwerke oder CDD-basierte Zeitquellen, für die kein nativer AUTOSAR-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) existiert, und erbt alle Attribute inklusive der ICV-Verifikationskonfiguration ohne eigene zusätzliche Attribute.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsmetadaten; zur Laufzeit steuern diese Attribute folgende Ablauflogik:</p>\n<ol class=\"fig-list\">\n<li><strong>Sicherheitsprüfung (<code>icvVerification</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer abgesicherten Zeitbotschaft.</li>\n<li>Überprüfung des Integrity Check Value (ICV) gemäß der parametrierten Verifikationsstrategie. Schlägt die Validierung fehl, wird die Synchronisationsnachricht verworfen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zwei-Schritt-Timeout (<code>followUpTimeoutValue</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer <code>SYNC</code>-PDU durch den Bus-Treiber/CDD.</li>\n<li>Start eines Software-Timers. Trifft die <code>FOLLOW_UP</code>-PDU nicht vor Ablauf von <code>followUpTimeoutValue</code> ein, wird der Synchronisationszyklus verworfen und ein Timeout-Flag an den <code>StbM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zeitsprungüberwachung (<code>timeLeapFutureThreshold</code> / <code>timeLeapPastThreshold</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Rekonstruktion der Master-Zeit $T_{Master}$ wird die Abweichung $\\Delta t = T_{Master} - T_{Local}$ berechnet.</li>\n<li>Überschreitet $\\Delta t > \\text{timeLeapFutureThreshold}$ oder $-\\Delta t > \\text{timeLeapPastThreshold}$, blockiert der Algorithmus die direkte Übernahme in die lokale Systemzeit oder triggert spezifische Synchronisationsfilter / DEM-Events.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Heilung (<code>timeLeapHealingCounter</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Feststellung eines Zeitsprungs inkrementiert jeder nachfolgende gültige Zyklus ($|\\Delta t| \\le \\text{Threshold}$) den internen Heilungszähler.</li>\n<li>Erst bei Erreichen von <code>timeLeapHealingCounter</code> gilt die Synchronisation wieder als stabil und fehlerfrei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>StbM</code> / CDD-Generierung):</strong></li>\n<li>Die Attribute mappen direkt in BSW-Konfigurationsparameter (z. B. <code>StbMTimeLeapFutureThreshold</code>, <code>StbMTimeLeapPastThreshold</code>, <code>StbMTimeLeapHealingCounter</code>).</li>\n<li>Fehlen die optionalen Attribute (<code>[0..1]</code>), greift das Default-Verhalten: Deaktivierung der jeweiligen Prüfung oder Verwendung von Stack-Defaults.</li>\n<li><strong>Treiber- und CDD-Entwickler:</strong></li>\n<li>Bei Implementierung eines <code>UserDefinedGlobalTimeSlave</code> (meist via Complex Device Driver) muss die Schnittstelle zum <code>StbM</code> (<code>StbM_BusSetGlobalTime</code> bzw. synchronisierte Zeitstempelübergabe) die im System-Template definierten Schwellwerte berücksichtigen.</li>\n<li>Das Follow-up-Timeout muss auf die Task-Zykluszeit und Jitter-Toleranzen des verwendeten proprietären Übertragungsmediums abgestimmt sein.</li>\n</ul>"}, {"id": "FIG-6cffe09ce0d74155", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Template, M1/M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> Global Time Synchronization (GTS) im AUTOSAR BSW-Stack (in Verbindung mit dem Synchronized Time-Base Manager, <code>StbM</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der generischen Parameter für einen Zeitsklaven (<code>GlobalTimeSlave</code>) und dessen Spezialisierung für herstellerspezifische oder nicht-standardisierte Busprotokolle/CDDs (<code>UserDefinedGlobalTimeSlave</code>). Es ermöglicht die systemweite Deklaration von Timeout- und Plausibilisierungsmechanismen (Time Leap / Sprungerkennung) für empfangene Zeitbasen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeSlave</code> (abstrakte Basisklasse, kursiv):</strong></li>\n</ul>\n<p class=\"fig-p\">Definiert die standardisierten Schutz-, Sicherheits- und Filterparameter eines zeitsynchronisierten Slaves:</p>\n<ul class=\"fig-list\">\n<li><code>+ followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Zeitspanne zwischen dem Empfang einer <code>SYNC</code>-Nachricht und der zugehörigen <code>FOLLOW_UP</code>-Nachricht (Zwei-Schritt-Synchronisationsverfahren).</li>\n<li><code>+ icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code>: Konfigurationsparameter zur Verifikation des Integrity Check Value (ICV) zur Absicherung der Zeitnachrichten gegen Manipulation und Übertragungsfehler.</li>\n<li><code>+ timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Zukunft (positive Phasendiskrepanz gegenüber der lokalen Zeitbasis).</li>\n<li><code>+ timeLeapHealingCounter: PositiveInteger [0..1]</code>: Anzahl aufeinanderfolgender, valider Synchronisationszyklen innerhalb der Schwellwerte, die erforderlich sind, um den Zustand eines zuvor detektierten Zeitsprungs (<code>Time Leap</code>) wieder aufzuheben (Entprellung/Heilung).</li>\n<li><code>+ timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Vergangenheit (negative Phasendiskrepanz).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>UserDefinedGlobalTimeSlave</code> (konkrete Klasse):</strong></li>\n<li>Spezialisierung via UML-Generalisierung (Vererbungspfeil mit geschlossener Spitze) von <code>GlobalTimeSlave</code>.</li>\n<li>Kapselt Slave-Instanzen für proprietäre Netzwerke oder CDD-basierte Zeitquellen, für die kein nativer AUTOSAR-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) existiert, und erbt alle Attribute inklusive der ICV-Verifikationskonfiguration ohne eigene zusätzliche Attribute.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsmetadaten; zur Laufzeit steuern diese Attribute folgende Ablauflogik:</p>\n<ol class=\"fig-list\">\n<li><strong>Sicherheitsprüfung (<code>icvVerification</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer abgesicherten Zeitbotschaft.</li>\n<li>Überprüfung des Integrity Check Value (ICV) gemäß der parametrierten Verifikationsstrategie. Schlägt die Validierung fehl, wird die Synchronisationsnachricht verworfen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zwei-Schritt-Timeout (<code>followUpTimeoutValue</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer <code>SYNC</code>-PDU durch den Bus-Treiber/CDD.</li>\n<li>Start eines Software-Timers. Trifft die <code>FOLLOW_UP</code>-PDU nicht vor Ablauf von <code>followUpTimeoutValue</code> ein, wird der Synchronisationszyklus verworfen und ein Timeout-Flag an den <code>StbM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zeitsprungüberwachung (<code>timeLeapFutureThreshold</code> / <code>timeLeapPastThreshold</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Rekonstruktion der Master-Zeit $T_{Master}$ wird die Abweichung $\\Delta t = T_{Master} - T_{Local}$ berechnet.</li>\n<li>Überschreitet $\\Delta t > \\text{timeLeapFutureThreshold}$ oder $-\\Delta t > \\text{timeLeapPastThreshold}$, blockiert der Algorithmus die direkte Übernahme in die lokale Systemzeit oder triggert spezifische Synchronisationsfilter / DEM-Events.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Heilung (<code>timeLeapHealingCounter</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Feststellung eines Zeitsprungs inkrementiert jeder nachfolgende gültige Zyklus ($|\\Delta t| \\le \\text{Threshold}$) den internen Heilungszähler.</li>\n<li>Erst bei Erreichen von <code>timeLeapHealingCounter</code> gilt die Synchronisation wieder als stabil und fehlerfrei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>StbM</code> / CDD-Generierung):</strong></li>\n<li>Die Attribute mappen direkt in BSW-Konfigurationsparameter (z. B. <code>StbMTimeLeapFutureThreshold</code>, <code>StbMTimeLeapPastThreshold</code>, <code>StbMTimeLeapHealingCounter</code>).</li>\n<li>Fehlen die optionalen Attribute (<code>[0..1]</code>), greift das Default-Verhalten: Deaktivierung der jeweiligen Prüfung oder Verwendung von Stack-Defaults.</li>\n<li><strong>Treiber- und CDD-Entwickler:</strong></li>\n<li>Bei Implementierung eines <code>UserDefinedGlobalTimeSlave</code> (meist via Complex Device Driver) muss die Schnittstelle zum <code>StbM</code> (<code>StbM_BusSetGlobalTime</code> bzw. synchronisierte Zeitstempelübergabe) die im System-Template definierten Schwellwerte berücksichtigen.</li>\n<li>Das Follow-up-Timeout muss auf die Task-Zykluszeit und Jitter-Toleranzen des verwendeten proprietären Übertragungsmediums abgestimmt sein.</li>\n</ul>"}, {"id": "FIG-0b25135798a5f677", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Template, M1/M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> Global Time Synchronization (GTS) im AUTOSAR BSW-Stack (in Verbindung mit dem Synchronized Time-Base Manager, <code>StbM</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der generischen Parameter für einen Zeitsklaven (<code>GlobalTimeSlave</code>) und dessen Spezialisierung für herstellerspezifische oder nicht-standardisierte Busprotokolle/CDDs (<code>UserDefinedGlobalTimeSlave</code>). Es ermöglicht die systemweite Deklaration von Timeout- und Plausibilisierungsmechanismen (Time Leap / Sprungerkennung) für empfangene Zeitbasen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeSlave</code> (abstrakte Basisklasse, kursiv):</strong></li>\n</ul>\n<p class=\"fig-p\">Definiert die standardisierten Schutz-, Sicherheits- und Filterparameter eines zeitsynchronisierten Slaves:</p>\n<ul class=\"fig-list\">\n<li><code>+ followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Zeitspanne zwischen dem Empfang einer <code>SYNC</code>-Nachricht und der zugehörigen <code>FOLLOW_UP</code>-Nachricht (Zwei-Schritt-Synchronisationsverfahren).</li>\n<li><code>+ icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code>: Konfigurationsparameter zur Verifikation des Integrity Check Value (ICV) zur Absicherung der Zeitnachrichten gegen Manipulation und Übertragungsfehler.</li>\n<li><code>+ timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Zukunft (positive Phasendiskrepanz gegenüber der lokalen Zeitbasis).</li>\n<li><code>+ timeLeapHealingCounter: PositiveInteger [0..1]</code>: Anzahl aufeinanderfolgender, valider Synchronisationszyklen innerhalb der Schwellwerte, die erforderlich sind, um den Zustand eines zuvor detektierten Zeitsprungs (<code>Time Leap</code>) wieder aufzuheben (Entprellung/Heilung).</li>\n<li><code>+ timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Vergangenheit (negative Phasendiskrepanz).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>UserDefinedGlobalTimeSlave</code> (konkrete Klasse):</strong></li>\n<li>Spezialisierung via UML-Generalisierung (Vererbungspfeil mit geschlossener Spitze) von <code>GlobalTimeSlave</code>.</li>\n<li>Kapselt Slave-Instanzen für proprietäre Netzwerke oder CDD-basierte Zeitquellen, für die kein nativer AUTOSAR-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) existiert, und erbt alle Attribute inklusive der ICV-Verifikationskonfiguration ohne eigene zusätzliche Attribute.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsmetadaten; zur Laufzeit steuern diese Attribute folgende Ablauflogik:</p>\n<ol class=\"fig-list\">\n<li><strong>Sicherheitsprüfung (<code>icvVerification</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer abgesicherten Zeitbotschaft.</li>\n<li>Überprüfung des Integrity Check Value (ICV) gemäß der parametrierten Verifikationsstrategie. Schlägt die Validierung fehl, wird die Synchronisationsnachricht verworfen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zwei-Schritt-Timeout (<code>followUpTimeoutValue</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer <code>SYNC</code>-PDU durch den Bus-Treiber/CDD.</li>\n<li>Start eines Software-Timers. Trifft die <code>FOLLOW_UP</code>-PDU nicht vor Ablauf von <code>followUpTimeoutValue</code> ein, wird der Synchronisationszyklus verworfen und ein Timeout-Flag an den <code>StbM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zeitsprungüberwachung (<code>timeLeapFutureThreshold</code> / <code>timeLeapPastThreshold</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Rekonstruktion der Master-Zeit $T_{Master}$ wird die Abweichung $\\Delta t = T_{Master} - T_{Local}$ berechnet.</li>\n<li>Überschreitet $\\Delta t > \\text{timeLeapFutureThreshold}$ oder $-\\Delta t > \\text{timeLeapPastThreshold}$, blockiert der Algorithmus die direkte Übernahme in die lokale Systemzeit oder triggert spezifische Synchronisationsfilter / DEM-Events.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Heilung (<code>timeLeapHealingCounter</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Feststellung eines Zeitsprungs inkrementiert jeder nachfolgende gültige Zyklus ($|\\Delta t| \\le \\text{Threshold}$) den internen Heilungszähler.</li>\n<li>Erst bei Erreichen von <code>timeLeapHealingCounter</code> gilt die Synchronisation wieder als stabil und fehlerfrei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>StbM</code> / CDD-Generierung):</strong></li>\n<li>Die Attribute mappen direkt in BSW-Konfigurationsparameter (z. B. <code>StbMTimeLeapFutureThreshold</code>, <code>StbMTimeLeapPastThreshold</code>, <code>StbMTimeLeapHealingCounter</code>).</li>\n<li>Fehlen die optionalen Attribute (<code>[0..1]</code>), greift das Default-Verhalten: Deaktivierung der jeweiligen Prüfung oder Verwendung von Stack-Defaults.</li>\n<li><strong>Treiber- und CDD-Entwickler:</strong></li>\n<li>Bei Implementierung eines <code>UserDefinedGlobalTimeSlave</code> (meist via Complex Device Driver) muss die Schnittstelle zum <code>StbM</code> (<code>StbM_BusSetGlobalTime</code> bzw. synchronisierte Zeitstempelübergabe) die im System-Template definierten Schwellwerte berücksichtigen.</li>\n<li>Das Follow-up-Timeout muss auf die Task-Zykluszeit und Jitter-Toleranzen des verwendeten proprietären Übertragungsmediums abgestimmt sein.</li>\n</ul>"}, {"id": "FIG-9985cc0d44e351bf", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt des AUTOSAR System Template, M1/M2-Ebene).</li>\n<li><strong>Architektur-Kontext:</strong> Global Time Synchronization (GTS) im AUTOSAR BSW-Stack (in Verbindung mit dem Synchronized Time-Base Manager, <code>StbM</code>).</li>\n<li><strong>Technischer Zweck:</strong> Modellierung der generischen Parameter für einen Zeitsklaven (<code>GlobalTimeSlave</code>) und dessen Spezialisierung für herstellerspezifische oder nicht-standardisierte Busprotokolle/CDDs (<code>UserDefinedGlobalTimeSlave</code>). Es ermöglicht die systemweite Deklaration von Timeout- und Plausibilisierungsmechanismen (Time Leap / Sprungerkennung) für empfangene Zeitbasen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>GlobalTimeSlave</code> (abstrakte Basisklasse, kursiv):</strong></li>\n</ul>\n<p class=\"fig-p\">Definiert die standardisierten Schutz-, Sicherheits- und Filterparameter eines zeitsynchronisierten Slaves:</p>\n<ul class=\"fig-list\">\n<li><code>+ followUpTimeoutValue: TimeValue [0..1]</code>: Maximal zulässige Zeitspanne zwischen dem Empfang einer <code>SYNC</code>-Nachricht und der zugehörigen <code>FOLLOW_UP</code>-Nachricht (Zwei-Schritt-Synchronisationsverfahren).</li>\n<li><code>+ icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code>: Konfigurationsparameter zur Verifikation des Integrity Check Value (ICV) zur Absicherung der Zeitnachrichten gegen Manipulation und Übertragungsfehler.</li>\n<li><code>+ timeLeapFutureThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Zukunft (positive Phasendiskrepanz gegenüber der lokalen Zeitbasis).</li>\n<li><code>+ timeLeapHealingCounter: PositiveInteger [0..1]</code>: Anzahl aufeinanderfolgender, valider Synchronisationszyklen innerhalb der Schwellwerte, die erforderlich sind, um den Zustand eines zuvor detektierten Zeitsprungs (<code>Time Leap</code>) wieder aufzuheben (Entprellung/Heilung).</li>\n<li><code>+ timeLeapPastThreshold: TimeValue [0..1]</code>: Schwellwert zur Erkennung eines unzulässigen Zeitsprungs in die Vergangenheit (negative Phasendiskrepanz).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>UserDefinedGlobalTimeSlave</code> (konkrete Klasse):</strong></li>\n<li>Spezialisierung via UML-Generalisierung (Vererbungspfeil mit geschlossener Spitze) von <code>GlobalTimeSlave</code>.</li>\n<li>Kapselt Slave-Instanzen für proprietäre Netzwerke oder CDD-basierte Zeitquellen, für die kein nativer AUTOSAR-Treiber (<code>CanTSyn</code>, <code>FrTSyn</code>, <code>EthTSyn</code>) existiert, und erbt alle Attribute inklusive der ICV-Verifikationskonfiguration ohne eigene zusätzliche Attribute.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm modelliert statische Konfigurationsmetadaten; zur Laufzeit steuern diese Attribute folgende Ablauflogik:</p>\n<ol class=\"fig-list\">\n<li><strong>Sicherheitsprüfung (<code>icvVerification</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer abgesicherten Zeitbotschaft.</li>\n<li>Überprüfung des Integrity Check Value (ICV) gemäß der parametrierten Verifikationsstrategie. Schlägt die Validierung fehl, wird die Synchronisationsnachricht verworfen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zwei-Schritt-Timeout (<code>followUpTimeoutValue</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trigger: Empfang einer <code>SYNC</code>-PDU durch den Bus-Treiber/CDD.</li>\n<li>Start eines Software-Timers. Trifft die <code>FOLLOW_UP</code>-PDU nicht vor Ablauf von <code>followUpTimeoutValue</code> ein, wird der Synchronisationszyklus verworfen und ein Timeout-Flag an den <code>StbM</code> gemeldet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zeitsprungüberwachung (<code>timeLeapFutureThreshold</code> / <code>timeLeapPastThreshold</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach erfolgreicher Rekonstruktion der Master-Zeit $T_{Master}$ wird die Abweichung $\\Delta t = T_{Master} - T_{Local}$ berechnet.</li>\n<li>Überschreitet $\\Delta t > \\text{timeLeapFutureThreshold}$ oder $-\\Delta t > \\text{timeLeapPastThreshold}$, blockiert der Algorithmus die direkte Übernahme in die lokale Systemzeit oder triggert spezifische Synchronisationsfilter / DEM-Events.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Heilung (<code>timeLeapHealingCounter</code>):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach Feststellung eines Zeitsprungs inkrementiert jeder nachfolgende gültige Zyklus ($|\\Delta t| \\le \\text{Threshold}$) den internen Heilungszähler.</li>\n<li>Erst bei Erreichen von <code>timeLeapHealingCounter</code> gilt die Synchronisation wieder als stabil und fehlerfrei.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Konfiguration (<code>StbM</code> / CDD-Generierung):</strong></li>\n<li>Die Attribute mappen direkt in BSW-Konfigurationsparameter (z. B. <code>StbMTimeLeapFutureThreshold</code>, <code>StbMTimeLeapPastThreshold</code>, <code>StbMTimeLeapHealingCounter</code>).</li>\n<li>Fehlen die optionalen Attribute (<code>[0..1]</code>), greift das Default-Verhalten: Deaktivierung der jeweiligen Prüfung oder Verwendung von Stack-Defaults.</li>\n<li><strong>Treiber- und CDD-Entwickler:</strong></li>\n<li>Bei Implementierung eines <code>UserDefinedGlobalTimeSlave</code> (meist via Complex Device Driver) muss die Schnittstelle zum <code>StbM</code> (<code>StbM_BusSetGlobalTime</code> bzw. synchronisierte Zeitstempelübergabe) die im System-Template definierten Schwellwerte berücksichtigen.</li>\n<li>Das Follow-up-Timeout muss auf die Task-Zykluszeit und Jitter-Toleranzen des verwendeten proprietären Übertragungsmediums abgestimmt sein.</li>\n</ul>"}], "trans": [{"from": "FIG-5de486b11c8e7a72", "to": "FIG-90e0e09024cc377c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>GlobalTimeSlave</code>: Schreibweise der Attributdefinitionen vereinheitlicht (Leerzeichen vor dem Doppelpunkt vor dem Datentyp entfernt, z. B. <code>followUpTimeoutValue: TimeValue [0..1]</code>).</li>\n</ul>"}, {"from": "FIG-90e0e09024cc377c", "to": "FIG-9ade626629365ba1", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>GlobalTimeSlave</code>: Attribut <code>+ icvVerification: GlobalTimeIcvVerificationEnum [0..1]</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-9ade626629365ba1", "to": "FIG-6cffe09ce0d74155", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6cffe09ce0d74155", "to": "FIG-0b25135798a5f677", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-0b25135798a5f677", "to": "FIG-9985cc0d44e351bf", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
